ReplacementContent:
"                                   return (
                                    <button 
                                      key={item.id} 
                                      disabled={isOutOfStock} 
                                      onClick={() => handleCatalogItemClick(item)} 
                                      className={`${isCompact ? 'h-[50px] p-2' : 'h-[120px]'} rounded border text-left flex flex-col relative overflow-hidden group transition-all ${isOutOfStock ? 'opacity-40 cursor-not-allowed' : 'hover:border-[#238636] hover:shadow-lg cursor-pointer active:scale-[0.98]'} ${isDark ? 'border-[#30363d] bg-[#0d1117]' : 'border-slate-200 bg-white hover:shadow-md'}`}
                                    >
                                      {isCompact ? (
                                        <div className="flex-1 flex flex-col justify-between w-full h-full p-0.5">
                                          <div className="flex justify-between items-center gap-1.5 w-full">
                                            <div className="flex flex-col min-w-0 flex-1">
                                              <span className={`text-[10px] font-bold uppercase truncate ${isDark ? 'text-white' : 'text-slate-900'}`}>
                                                {item.product_name || item.name}
                                              </span>
                                              {posSettings.showItemsCodeDetails && item.code && (
                                                <span className={`text-[7px] font-mono leading-none ${isDark ? 'text-gray-400' : 'text-slate-500'}`}>
                                                  #{item.code}
                                                </span>
                                              )}
                                            </div>"
